await page.setViewportSize({ width: 1280, height: 720 });
await page.goto("file:///Users/melvynx/Developer/agent-benchmarks/benchmarks/little-red-riding-hood-film/2026-09-21-cursor-agent-grok-4-7-high/index.html");
