const h1 = await page.locator("h1").textContent();
const early = await page.evaluate(() => {
  const s = window.__RED_HOOD_FILM__.snapshot();
  return { time: s.time, playing: s.playing, seed: s.seed, speed: s.speed, name: s.sequenceName };
});
await page.waitForTimeout(700);
const later = await page.evaluate(() => window.__RED_HOOD_FILM__.snapshot().time);
const times = [0, 4500, 9000, 12000, 20000, 31000, 35000, 42000, 46000, 47500, 52000, 56000, 60000, 64000, 70000, 73000, 79000, 86000, 90000, 93000, 98000, 102000, 108000, 112000];
