  await saveScreenshot(buf, "rrh-" + String(t).padStart(6, "0") + ".png");
}
await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(200);
await page.evaluate(() => window.__RED_HOOD_FILM__.seek(2000));
