await saveScreenshot(await page.screenshot(), "rrh-mobile-forest.png");
await page.evaluate(() => window.__RED_HOOD_FILM__.seek(108000));
await saveScreenshot(await page.screenshot(), "rrh-mobile-dawn.png");
await page.setViewportSize({ width: 1280, height: 720 });
