  title, h1, early, later, advanced: later > early.time,
  passed: test.passed,
  failed,
  testCount: test.tests.length,
  restored: { seed: restored.seed, time: restored.time, playing: restored.playing, speed: restored.speed },
  errors, reqs
}, null, 2));
EOF

